    let south = graph.add_node(*edge2_points.last().unwrap(), NodeType::Junction);
    graph.add_edge(test_edge(
        west,
        center,
        edge0_points.clone(),
        7.0,
        EdgeClass::Standard,
        TransitType::Road,
        TransitFlags::CAR | TransitFlags::FOOT,
    ));
    graph.add_edge(test_edge(
        center,
        east,
        edge1_points.clone(),
        7.0,
        EdgeClass::Standard,
        TransitType::Road,
        TransitFlags::CAR | TransitFlags::FOOT,
    ));
